    psionics: { type: "major", isp_base: "M.E. + 8, +2d4 per level", powers: ["Empathy", "Mind Block", "Telepathy"], powers_starting: 4, categories_allowed: ["Healing", "Physical", "Sensitive"] }
  - name: "Psionics (91-00): Lemurian Master Psychic"
